#                     (m   (shift-left pos (- 5ul s)))
#                     (wr  (~ twr m))
#                     (wi  (~ twi m))
#                     (ar  (~ re i0))
#                     (ai  (~ im i0))
#                     (cr  (~ re i1))
#                     (ci  (~ im i1))
#                     (br  (- (* cr wr) (* ci wi)))
