#                 (set! (~ re i1) (- ar br))
#                 (set! (~ im i1) (- ai bi))))))
#         (sync-workgroup)))
#     ;; columns 0 .. 32: DIF along y, span hs = 32, 16, .. 1
#     (dotimes (s 6ul)
#       (let ((hs (shift-right 32ul s)))
#         (dotimes (j 5ul)
#           (let ((idx (+ tid (* j 256ul))))
#             (when (< idx 1056ul)
#               (let ((cx  (rem idx 33ul))
#                     (bk  (/ idx 33ul))
#                     (pos (logand bk (- hs 1ul)))
